package com.example.campsitelottery

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Before
import org.junit.Test

/**
 * Documentation generated by Claude
 * Tests the rating flow against [InMemoryRatingRepository].
 */
class InMemoryRatingRepositoryTest {

    private lateinit var repo: InMemoryRatingRepository

    @Before
    fun setUp() {
        repo = InMemoryRatingRepository(listOf(Campsite(campsiteId = "site1", ownerId = "owner")))
    }

    private fun submit(userId: String, stars: Int, campsiteId: String = "site1"): Exception? {
        var error: Exception? = null
        repo.submitRating(campsiteId, userId, stars, onSuccess = {}, onFailure = { error = it })
        return error
    }

    private fun myRating(userId: String): Int? {
        var result: Int? = -1
        repo.getMyRating("site1", userId, onSuccess = { result = it }, onFailure = { throw it })
        return result
    }

    @Test
    fun noRatingBeforeSubmitting() {
        assertNull(myRating("guest"))
    }

    @Test
    fun submittedRatingIsSavedAndAveraged() {
        assertNull(submit("guest1", 5))
        assertNull(submit("guest2", 2))
        assertEquals(5, myRating("guest1"))
        assertEquals(RatingPolicy.Totals(sum = 7, count = 2), repo.totalsFor("site1"))
    }

    @Test
    fun ratingAgainReplacesTheEarlierRating() {
        submit("guest", 1)
        submit("guest", 4)
        assertEquals(4, myRating("guest"))
        assertEquals(RatingPolicy.Totals(sum = 4, count = 1), repo.totalsFor("site1"))
    }

    @Test
    fun ownerCannotRateOwnCampsite() {
        assertNotNull(submit("owner", 5))
        assertEquals(RatingPolicy.Totals(), repo.totalsFor("site1"))
    }

    @Test
    fun invalidStarsAreRejected() {
        assertNotNull(submit("guest", 0))
        assertNull(myRating("guest"))
    }

    @Test
    fun unknownCampsiteIsRejected() {
        assertNotNull(submit("guest", 3, campsiteId = "missing"))
    }
}
